const casos = $('Casos de prueba').all();
const catalogo = $('Armar catálogo').first().json.items;
const resp = $input.all();
const norm = s => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/\s+/g, ' ').trim();
let okInt = 0, okDisp = 0, okIA = 0, nDisp = 0, corregidos = 0;
const detalle = [];
resp.forEach((r, i) => {
  const c = casos[i].json;
  let d;
  try { d = JSON.parse(r.json.content[0].text.replace(/```json|```/g, '').trim()); }
  catch (e) { d = { intencion: 'error_json', referencia: null, disponible: null, respuesta: '' }; }
  const okI = d.intencion === c.intencion;
  if (okI) okInt++;
  let okD = null, dispFinal = d.disponible, corregido = false;
  if (c.intencion === 'busqueda') {
    nDisp++;
    if (d.disponible === c.disponible) okIA++;
    const item = d.referencia ? catalogo.find(x => norm(x.referencia) === norm(d.referencia)) : null;
    dispFinal = !!(item && item.existencias > 0);
    corregido = dispFinal !== d.disponible;
    if (corregido) corregidos++;
    okD = dispFinal === c.disponible;
    if (okD) okDisp++;
  }
  detalle.push({ n: i + 1, mensaje: c.mensaje, esperado: c.intencion, obtenido: d.intencion, referencia: d.referencia, disp_esperado: c.disponible, disp_ia: d.disponible, disp_final: dispFinal, corregido, correcto: okI && okD !== false, respuesta: d.respuesta });
});
return [{ json: { total: resp.length, aciertos_intencion: okInt, pct_intencion: Math.round(okInt / resp.length * 100), casos_disponibilidad: nDisp, aciertos_disponibilidad_final: okDisp, pct_disponibilidad_final: Math.round(okDisp / nDisp * 100), aciertos_disponibilidad_solo_ia: okIA, correcciones_del_codigo: corregidos, fallos: detalle.filter(x => !x.correcto), detalle } }];

const items = $input.all().map(i => ({ referencia: i.json.referencia, existencias: Number(i.json.existencias) }));
const texto = items.map(i => `- ${i.referencia} | ${i.existencias}`).join('\n');
return [{ json: { texto, items } }];

